"""Portfolio tester: 7 sub-programs (runs/evolve_overnight/candidates/cand1_gen037_0.6994.py, evolve/proposals/macrosweep.py, evolve/proposals/wallbreaker.py, evolve/proposals/resonator.py, evolve/proposals2/targetcycle.py, evolve/proposals2/pairladder.py, evolve/proposals2/rrtdrive.py). Worker i runs sub-program i % n; archive slots are partitioned per sub-program."""
import jax, jax.numpy as jnp

# EVOLVE-BLOCK-START
_SRC = ['"""Tester program (evolvable). The four hooks below define how a batch of B workers explores a Kinetix level.\nKinetix states are save/restore-able: the harness keeps K archive slots; `restore` may jump a worker to a stored\nstate, `archive` may store the worker\'s current state. Everything must be pure JAX (jit/vmap-compatible, fixed shapes).\n\nFeature vector `feats` (per worker, F floats, oracle-blind):\n  [0:2] dyn_pos (centroid of moving shapes), [2:4] dyn_vel, [4] dyn_max_speed, [5:7] green_pos, [7] green_blue_dist,\n  [8] time_frac, [9:11] blue_pos, then per-polygon pos/vel/rot/active/role blocks, per-circle pos/vel/active/role blocks,\n  then contact flags. `obs` is Kinetix\'s symbolic observation. Actions: 0..2*NM-1 motor +/- (NM=4 motor bindings),\n  2*NM = no-op, 2*NM+1.. thrusters (2 bindings).\nGoal of the search: reach states that expose planted defects as fast as possible (steps-to-first-witness), and do so\nin a way that generalizes to defect classes the search never saw."""\nimport jax, jax.numpy as jnp\n\n# EVOLVE-BLOCK-START\nBITS = 12            # hash bits for coverage-pool archive cells\nP_RESTORE = 0.06      # per-step probability that a worker jumps to an archived state\nMAX_SHORT = 5         # max repeat length for short random-exploration holds\nMAX_MED = 14          # max repeat length for medium thruster-biased holds\nMAX_LONG = 42         # max repeat length for long single-direction / thruster holds (energy pumping)\nMAX_PUMP = 60          # max repeat length for resonant motor-oscillation holds (swing-pump energy buildup)\nCELL_DIMS = (0, 1, 2, 3, 5, 6, 9, 10)   # feature dims used to define coverage cells\nCELL_RES = 0.5        # coarse grid resolution for coverage cells\nPOOL_FRAC = (0.55, 0.25, 0.20)   # coverage / speed / proximity pool fractions of K\nEXTREME_BONUS = 0.38  # restore-logit bonus for speed/proximity pool slots\nNM = 4                # motor bindings (fixed by env spec)\ndef _split(K):\n    K1 = max(1, int(round(POOL_FRAC[0] * K)))\n    K2 = max(1, int(round(POOL_FRAC[1] * K)))\n    K1 = max(1, K - K2 - max(1, K - K1 - K2))\n    K3 = max(1, K - K1 - K2)\n    K1 = K - K2 - K3\n    return K1, K2, K3\ndef init(rng, F, n_act, K, B):\n    K1, K2, K3 = _split(K)\n    return {"n_act": jnp.int32(n_act), "K": jnp.int32(K), "cur": jnp.zeros(B, jnp.int32),\n            "left": jnp.zeros(B, jnp.int32), "mode": jnp.zeros(B, jnp.int32),\n            "osc_motor": jnp.zeros(B, jnp.int32), "osc_period": jnp.ones(B, jnp.int32),\n            "proj": jax.random.normal(rng, (len(CELL_DIMS), BITS)),\n            "cell_slot": jnp.full(2 ** BITS, -1, jnp.int32), "next_free": jnp.int32(0)}\ndef _cell(mem, feats):\n    x = jnp.round(feats[:, jnp.array(CELL_DIMS)] / CELL_RES) * CELL_RES\n    return ((x @ mem["proj"] > 0) * (2 ** jnp.arange(BITS))).sum(-1).astype(jnp.int32)\ndef restore(mem, feats, arch_feats, arch_valid, arch_visits, rng):\n    B = feats.shape[0]; K = arch_valid.shape[0]\n    K1, K2, K3 = _split(K)\n    k1, k2 = jax.random.split(rng)\n    do = jax.random.uniform(k1, (B,)) < P_RESTORE\n    idx = jnp.arange(K)\n    bonus = jnp.where(idx >= K1, EXTREME_BONUS, 0.0)\n    logits = jnp.where(arch_valid, -0.5 * jnp.log1p(arch_visits.astype(jnp.float32)) + bonus, -jnp.inf)\n    slot = jnp.argmax(logits[None, :] + jax.random.gumbel(k2, (B, K)), axis=1)\n    return do & arch_valid.any(), slot, mem\ndef act(mem, feats, obs, rng):\n    B = feats.shape[0]; n_act = mem["n_act"]\n    k1, k2, k3, k4, k5, k6, k7 = jax.random.split(rng, 7)\n    new = mem["left"] <= 0\n    # 0: short random exploration, 1: long single-motor energy pump, 2: medium thruster hold,\n    # 3: long thruster burst, 4: resonant motor oscillation (swing-pump for extra kinetic energy)\n    mode_probs = jnp.array([0.20, 0.20, 0.20, 0.20, 0.20])\n    mode_probs = jnp.array([0.15, 0.22, 0.15, 0.20, 0.28])   # favor energy-building modes (1,3,4) for TUNNEL\n    mode = jnp.where(new, jax.random.choice(k1, 5, (B,), p=mode_probs), mem["mode"])\n    rand_action = jax.random.randint(k2, (B,), 0, n_act)\n    thr_lo = 2 * NM + 1\n    thr_span = jnp.maximum(n_act - thr_lo, 1)\n    thr_action = thr_lo + jax.random.randint(k3, (B,), 0, thr_span)\n    thr_action = jnp.where(n_act > thr_lo, thr_action, rand_action)\n    is_thruster_mode = (mode == 2) | (mode == 3)\n    new_action = jnp.where(is_thruster_mode, thr_action, rand_action)\n    short_len = jax.random.randint(k4, (B,), 1, MAX_SHORT + 1)\n    med_len = jax.random.randint(k4, (B,), 6, MAX_MED + 1)\n    long_len = jax.random.randint(k5, (B,), 15, MAX_LONG + 1)\n    pump_len = jax.random.randint(k5, (B,), 30, MAX_PUMP + 1)\n    rep_len = jnp.where(mode == 4, pump_len,\n                         jnp.where((mode == 1) | (mode == 3), long_len, jnp.where(mode == 2, med_len, short_len)))\n    osc_motor = jnp.where(new & (mode == 4), jax.random.randint(k6, (B,), 0, NM), mem["osc_motor"])\n    osc_period = jnp.where(new & (mode == 4), jax.random.randint(k7, (B,), 2, 17), mem["osc_period"])\n    left = jnp.where(new, rep_len, mem["left"]) - 1\n    osc_sign = jnp.mod(left // jnp.maximum(osc_period, 1), 2)\n    pump_action = 2 * osc_motor + osc_sign\n    cur = jnp.where(new, new_action, mem["cur"])\n    cur = jnp.where(mode == 4, pump_action, cur)\n    return cur, {**mem, "cur": cur, "left": left, "mode": mode, "osc_motor": osc_motor, "osc_period": osc_period}\ndef archive(mem, feats, done, arch_feats, arch_valid, rng):\n    K = arch_valid.shape[0]\n    K1, K2, K3 = _split(K)\n    live = ~done\n    # coverage pool: hash-grid novelty over first K1 slots\n    cell = _cell(mem, feats)\n    is_new_cell = (mem["cell_slot"][cell] < 0) & live\n    order = jnp.cumsum(is_new_cell) - 1\n    cov_slot = (mem["next_free"] + order) % K1\n    # speed pool: keep the K2 highest dyn_max_speed states seen\n    sub_speed = arch_feats[K1:K1 + K2, 4]\n    sub_speed_valid = arch_valid[K1:K1 + K2]\n    masked_speed = jnp.where(sub_speed_valid, sub_speed, -jnp.inf)\n    worst_speed_idx = jnp.argmin(masked_speed)\n    worst_speed_val = masked_speed[worst_speed_idx]\n    speed_beats = (feats[:, 4] > worst_speed_val) & live\n    speed_slot = K1 + worst_speed_idx\n    # proximity pool: keep the K3 states with smallest green_blue_dist\n    sub_dist = arch_feats[K1 + K2:K, 7]\n    sub_dist_valid = arch_valid[K1 + K2:K]\n    masked_dist = jnp.where(sub_dist_valid, sub_dist, jnp.inf)\n    worst_dist_idx = jnp.argmax(masked_dist)\n    worst_dist_val = masked_dist[worst_dist_idx]\n    dist_beats = (feats[:, 7] < worst_dist_val) & live\n    dist_slot = K1 + K2 + worst_dist_idx\n    use_speed = speed_beats & ~is_new_cell\n    use_dist = dist_beats & ~is_new_cell & ~use_speed\n    do = is_new_cell | use_speed | use_dist\n    slot = jnp.where(is_new_cell, cov_slot, jnp.where(use_speed, speed_slot, dist_slot))\n    cell_slot = mem["cell_slot"].at[jnp.where(is_new_cell, cell, 0)].set(\n        jnp.where(is_new_cell, cov_slot, mem["cell_slot"][0]))\n    return do, slot, {**mem, "cell_slot": cell_slot, "next_free": (mem["next_free"] + is_new_cell.sum()) % K1}\n# EVOLVE-BLOCK-END\n\n\n', '"""Checkpointed action-macro sweep ("macrosweep") -- a breadth-first tree search over structured action programs.\n\nIdea: sticky-random actions almost never produce the *coherent* input programs a human tester tries first: hold one\nmotor to the stop for a second, reverse it rhythmically, fire a thruster continuously, pulse it, sweep every motor in\nturn. This program enumerates such macros deterministically instead of sampling them.\n(1) act() replays a fixed library of ~36 macros (sustained holds, fast/slow reversals, thruster holds and pulse\n    trains, thruster+motor interleaves, all-motor sweeps, a settle macro, and short-burst variants for finer\n    branching); each worker advances to the next macro in the library every time one finishes, so the batch sweeps\n    the whole library rather than re-sampling the same few behaviours.\n(2) The archive is the search *frontier*: a macro endpoint is stored only if it is farther than NOV_EPS from every\n    stored state in a scaled position/velocity metric, plus any mid-macro state that gets unusually fast.\n(3) restore() fires exactly when a macro finishes and sends each worker to a *different* least-expanded frontier node\n    (ranked by the harness\'s visit counts, with noise for ties). The result is a breadth-first expansion of the\n    (state x macro) product: depth comes from chaining macros through checkpoints, breadth from the library.\n"""\nimport jax, jax.numpy as jnp\n\n# EVOLVE-BLOCK-START\nMACRO_L = 20        # length of a full macro\nSHORT_L = 6         # length of the short-burst macros (finer branching factor)\nNOV_EPS = 0.30      # novelty radius (scaled feature units) required to store an endpoint\nNOV_DIMS = (0, 1, 2, 3, 4, 5, 6, 9, 10)                    # dyn pos/vel/speed, green pos, blue pos\nNOV_SCALE = (1.0, 1.0, 0.25, 0.25, 0.25, 1.0, 1.0, 1.0, 1.0)\nEPS_RAND = 0.03     # tiny action noise, breaks symmetry between workers on identical checkpoints\nSPD_HOT = 4.0       # mid-macro store threshold on dyn_max_speed\nVIS_NOISE = 0.9     # tie-break noise on the frontier visit ranking\n\n\ndef _macros(n_act):\n    """Deterministic macro library: (M, MACRO_L) action table + per-macro length."""\n    nm = max(1, (n_act - 3) // 2); noop = 2 * nm\n    thr = [noop + 1 + t for t in range(max(0, n_act - 1 - 2 * nm))] or [noop]\n    ms = []\n    def add(pat, L): ms.append(([int(pat[i % len(pat)]) for i in range(MACRO_L)], L))\n    for m in range(nm):\n        add([2 * m], MACRO_L); add([2 * m + 1], MACRO_L)                    # sustained pushes\n        add([2 * m, 2 * m, 2 * m + 1, 2 * m + 1], MACRO_L)                  # fast reversal\n        add([2 * m] * 5 + [2 * m + 1] * 5, MACRO_L)                         # slow reversal\n    for t in thr:\n        add([t], MACRO_L); add([t, t, noop, noop], MACRO_L)                 # thruster hold / pulse train\n    for m in range(nm):\n        add([thr[m % len(thr)], 2 * m], MACRO_L)                            # thrust + motor interleave\n    add([2 * m for m in range(nm)], MACRO_L); add([2 * m + 1 for m in range(nm)], MACRO_L)\n    add([noop], MACRO_L)                                                    # settle\n    for m in range(nm):\n        add([2 * m], SHORT_L); add([2 * m + 1], SHORT_L)                    # short bursts\n    add([thr[0], noop], SHORT_L)\n    return [p for p, _ in ms], [L for _, L in ms]\n\n\ndef init(rng, F, n_act, K, B):\n    tab, ln = _macros(n_act)\n    M = len(tab)\n    return {"n_act": jnp.int32(n_act), "K": jnp.int32(K), "M": jnp.int32(M),\n            "table": jnp.array(tab, jnp.int32), "mlen": jnp.array(ln, jnp.int32),\n            "nov": jnp.array(NOV_DIMS, jnp.int32), "sc": jnp.array(NOV_SCALE, jnp.float32),\n            "mid": jnp.arange(B, dtype=jnp.int32) % jnp.int32(M), "ph": jnp.zeros(B, jnp.int32),\n            "at_end": jnp.zeros(B, bool), "next_free": jnp.int32(0)}\n\n\ndef restore(mem, feats, arch_feats, arch_valid, arch_visits, rng):\n    B = feats.shape[0]; K = arch_valid.shape[0]\n    key = jnp.where(arch_valid, arch_visits.astype(jnp.float32) + VIS_NOISE * jax.random.uniform(rng, (K,)), 1e6)\n    slot = jnp.argsort(key)[jnp.arange(B) % K]           # distinct least-expanded frontier nodes\n    return mem["at_end"] & arch_valid.any(), slot, mem\n\n\ndef act(mem, feats, obs, rng):\n    B = feats.shape[0]; k1, k2 = jax.random.split(rng)\n    ph = jnp.clip(mem["ph"], 0, mem["table"].shape[1] - 1)\n    a = mem["table"][mem["mid"], ph]\n    a = jnp.where(jax.random.uniform(k1, (B,)) < EPS_RAND, jax.random.randint(k2, (B,), 0, mem["n_act"]), a)\n    nxt = mem["ph"] + 1\n    end = nxt >= mem["mlen"][mem["mid"]]\n    return a.astype(jnp.int32), {**mem, "ph": jnp.where(end, 0, nxt),\n                                 "mid": jnp.where(end, (mem["mid"] + 1) % mem["M"], mem["mid"]), "at_end": end}\n\n\ndef archive(mem, feats, done, arch_feats, arch_valid, rng):\n    B = feats.shape[0]; K = arch_valid.shape[0]\n    x = feats[:, mem["nov"]] * mem["sc"]\n    y = arch_feats[:, mem["nov"]] * mem["sc"]\n    d2 = ((x[:, None, :] - y[None, :, :]) ** 2).sum(-1)\n    mind = jnp.min(jnp.where(arch_valid[None, :], d2, 1e12), axis=1)\n    store = (~done) & (mem["at_end"] | (feats[:, 4] > SPD_HOT)) & (mind > NOV_EPS ** 2)\n    slot = (mem["next_free"] + jnp.cumsum(store) - 1) % mem["K"]\n    return store, slot, {**mem, "next_free": (mem["next_free"] + store.sum()) % mem["K"]}\n# EVOLVE-BLOCK-END\n\n\n', '"""Boundary-seeking escape search ("wallbreaker").\n\nIdea: most planted defects that matter live at the *edges* of the reachable set, so this program optimises a single\nscalar -- how far the outermost movable shape is from the arena centre, plus how fast it is still moving outward.\n(1) A self-calibrating mobility mask learns online which shape indices ever move, so static walls (which sit outside\n    the box and would dominate any extremeness statistic) are excluded automatically without any oracle knowledge.\n(2) act() is a per-worker (1+1) hill-climber on the action *distribution*: each worker holds a preference logit vector,\n    perturbs it every HOLD steps, and keeps the perturbation only if the batch of steps made progress along the\n    worker\'s assigned compass direction; stalled workers pick a new direction. This finds sustained directional pushes\n    that sticky-random actions almost never produce.\n(3) The archive is an elite pool over the boundary score: each step the weakest slots are offered to the workers and\n    overwritten only by strictly better states, so restores branch from the current record-holders (plus a small\n    random-slot channel for diversity). Escaping the box (OOB), ramming a wall hard enough to pass through a\n    non-solid obstacle (TUNNEL) and extreme sustained pushes (ANOMALY) all fall out of the same objective.\n"""\nimport jax, jax.numpy as jnp\n\n# EVOLVE-BLOCK-START\nCENTER = 2.5        # centre of the 5x5 arena; scores are measured relative to it\nBETA_VEL = 0.5      # weight of the outward radial velocity in the boundary score\nMOB_THR = 0.03      # speed above which a shape index is considered movable (learned online)\nP_BASE = 0.02       # baseline per-step restore probability\nP_STALL = 0.30      # restore probability once a worker has stalled\nSTALL_T = 20        # steps without a new outward record before a worker counts as stalled\nREDIR_T = 60        # steps stalled before a worker draws a new escape direction\nTEMP = 1.5          # inverse temperature on archive boundary scores\nHOLD = 8            # length of one hill-climbing trial block\nSIGMA = 1.5         # perturbation scale of the action-preference logits\nSTICKY = 0.55       # probability of repeating the previous action inside a block\nEPS_RAND = 0.10     # uniform-random action rate\nMARGIN = 0.01       # improvement required to evict an elite slot\nP_DIVERSE = 0.07    # probability of storing into a random slot regardless of score\nDIRS = ((1.0, 0.0), (0.7071, 0.7071), (0.0, 1.0), (-0.7071, 0.7071),\n        (-1.0, 0.0), (-0.7071, -0.7071), (0.0, -1.0), (0.7071, -0.7071))\n\n\ndef _idx(F):\n    """Recover the per-shape feature blocks from the feature width (unique for every Kinetix size)."""\n    sols = [(p, c) for p in range(4, 41) for c in range(0, 41)\n            if 11 + 7 * p + 6 * c + (p * (p - 1) // 2 - 6) + c * p + c * (c - 1) // 2 == F]\n    if len(sols) != 1:\n        return dict(use=0.0, px=[0], py=[1], vx=[2], vy=[3], ai=[8])\n    Np, Nc = sols[0]\n    P = 11; PV = P + 2 * Np; PA = PV + 2 * Np + Np; C = PA + 2 * Np; CV = C + 2 * Nc; CA = CV + 2 * Nc\n    return dict(use=1.0,\n                px=[P + 2 * i for i in range(Np)] + [C + 2 * i for i in range(Nc)],\n                py=[P + 2 * i + 1 for i in range(Np)] + [C + 2 * i + 1 for i in range(Nc)],\n                vx=[PV + 2 * i for i in range(Np)] + [CV + 2 * i for i in range(Nc)],\n                vy=[PV + 2 * i + 1 for i in range(Np)] + [CV + 2 * i + 1 for i in range(Nc)],\n                ai=[PA + i for i in range(Np)] + [CA + i for i in range(Nc)])\n\n\ndef _w(mem, X):\n    """Weights of shapes that are active AND have been seen to move (walls therefore get weight 0)."""\n    return X[:, mem["ai"]] * (mem["mob"] > MOB_THR).astype(jnp.float32) * mem["use"]\n\n\ndef _out_score(mem, X):\n    """How close to / far past the box boundary the outermost movable shape is (+ outward momentum). X: (N, F)."""\n    dx = X[:, mem["px"]] - CENTER; dy = X[:, mem["py"]] - CENTER\n    vx = X[:, mem["vx"]]; vy = X[:, mem["vy"]]\n    rad = (dx * vx + dy * vy) / (jnp.sqrt(dx * dx + dy * dy) + 1e-3)\n    s = jnp.maximum(jnp.abs(dx), jnp.abs(dy)) + BETA_VEL * jnp.tanh(0.3 * rad)\n    s_shape = jnp.max(jnp.where(_w(mem, X) > 0.5, s, -1e6), axis=-1)\n    cx = X[:, 0] - CENTER; cy = X[:, 1] - CENTER\n    crad = (cx * X[:, 2] + cy * X[:, 3]) / (jnp.sqrt(cx * cx + cy * cy) + 1e-3)\n    s_cent = jnp.maximum(jnp.abs(cx), jnp.abs(cy)) + BETA_VEL * jnp.tanh(0.3 * crad)\n    return jnp.maximum(s_shape, s_cent)\n\n\ndef _progress(mem, X, d):\n    """Signed extent of the movable shapes along each row\'s escape direction d: (N, 2)."""\n    px = X[:, mem["px"]] - CENTER; py = X[:, mem["py"]] - CENTER\n    proj = px * d[:, 0:1] + py * d[:, 1:2]\n    p_shape = jnp.max(jnp.where(_w(mem, X) > 0.5, proj, -1e6), axis=-1)\n    return jnp.maximum(p_shape, (X[:, 0] - CENTER) * d[:, 0] + (X[:, 1] - CENTER) * d[:, 1])\n\n\ndef init(rng, F, n_act, K, B):\n    ix = _idx(F); k1, k2 = jax.random.split(rng)\n    dirs = jnp.array(DIRS, jnp.float32)\n    return {"n_act": jnp.int32(n_act),\n            "px": jnp.array(ix["px"], jnp.int32), "py": jnp.array(ix["py"], jnp.int32),\n            "vx": jnp.array(ix["vx"], jnp.int32), "vy": jnp.array(ix["vy"], jnp.int32),\n            "ai": jnp.array(ix["ai"], jnp.int32), "use": jnp.float32(ix["use"]),\n            "mob": jnp.zeros(len(ix["px"]), jnp.float32),\n            "dirs": dirs, "dir": dirs[jax.random.randint(k1, (B,), 0, len(DIRS))],\n            "base": jnp.zeros((B, n_act), jnp.float32),\n            "trial": SIGMA * jax.random.normal(k2, (B, n_act), jnp.float32),\n            "best": jnp.full((B,), -1e6, jnp.float32), "p0": jnp.zeros(B, jnp.float32),\n            "pmax": jnp.full((B,), -1e6, jnp.float32), "stall": jnp.zeros(B, jnp.int32),\n            "left": jnp.zeros(B, jnp.int32), "cur": jnp.zeros(B, jnp.int32),\n            "sscore": jnp.full(K + 1, -1e6, jnp.float32)}\n\n\ndef restore(mem, feats, arch_feats, arch_valid, arch_visits, rng):\n    B = feats.shape[0]; K = arch_valid.shape[0]; k1, k2 = jax.random.split(rng)\n    s = _out_score(mem, arch_feats) - 0.15 * jnp.log1p(arch_visits.astype(jnp.float32))\n    logits = jnp.where(arch_valid, TEMP * s, -1e9)\n    slot = jnp.argmax(logits[None, :] + jax.random.gumbel(k2, (B, K), jnp.float32), axis=1)\n    p = jnp.where(mem["stall"] > STALL_T, P_STALL, P_BASE)\n    do = (jax.random.uniform(k1, (B,)) < p) & arch_valid.any()\n    return do, slot, {**mem, "stall": jnp.where(do, 0, mem["stall"]),\n                      "pmax": jnp.where(do, jnp.float32(-1e6), mem["pmax"])}\n\n\ndef act(mem, feats, obs, rng):\n    B = feats.shape[0]; k1, k2, k3, k4, k5, k6 = jax.random.split(rng, 6)\n    prog = _progress(mem, feats, mem["dir"])\n    newb = mem["left"] <= 0\n    better = (prog - mem["p0"]) > mem["best"]\n    base = jnp.where((newb & better)[:, None], mem["trial"], mem["base"])\n    upd = jnp.maximum(jnp.where(better, prog - mem["p0"], mem["best"] * 0.9), 0.0)\n    best = jnp.where(newb, upd, mem["best"])\n    trial = jnp.where(newb[:, None], base + SIGMA * jax.random.normal(k1, base.shape, jnp.float32), mem["trial"])\n    a = jax.random.categorical(k2, trial)\n    a = jnp.where(jax.random.uniform(k3, (B,)) < EPS_RAND, jax.random.randint(k4, (B,), 0, mem["n_act"]), a)\n    a = jnp.where((jax.random.uniform(k5, (B,)) < STICKY) & ~newb, mem["cur"], a).astype(jnp.int32)\n    stall = jnp.where(prog > mem["pmax"] + 1e-3, 0, mem["stall"] + 1)\n    pmax = jnp.maximum(mem["pmax"], prog)\n    redir = stall > REDIR_T\n    d = jnp.where(redir[:, None], mem["dirs"][jax.random.randint(k6, (B,), 0, len(DIRS))], mem["dir"])\n    return a, {**mem, "base": base, "trial": trial, "best": best, "cur": a,\n               "p0": jnp.where(newb, prog, mem["p0"]), "left": jnp.where(newb, HOLD, mem["left"]) - 1,\n               "pmax": jnp.where(redir, prog, pmax), "stall": jnp.where(redir, 0, stall), "dir": d}\n\n\ndef archive(mem, feats, done, arch_feats, arch_valid, rng):\n    B = feats.shape[0]; K = arch_valid.shape[0]; k1, k2 = jax.random.split(rng)\n    spd = jnp.sqrt(feats[:, mem["vx"]] ** 2 + feats[:, mem["vy"]] ** 2) * feats[:, mem["ai"]]\n    mob = jnp.maximum(mem["mob"], spd.max(0) * mem["use"])\n    sc = _out_score({**mem, "mob": mob}, feats)\n    eff = jnp.where(arch_valid, mem["sscore"][:K], jnp.float32(-1e6))\n    tgt = jnp.argsort(eff)[jnp.arange(B) % K]\n    div = jax.random.uniform(k1, (B,)) < P_DIVERSE\n    slot = jnp.where(div, jax.random.randint(k2, (B,), 0, K), tgt)\n    store = (~done) & (div | (sc > eff[tgt] + MARGIN))\n    sscore = mem["sscore"].at[jnp.where(store, slot, K)].set(jnp.where(store, sc, mem["sscore"][K]))\n    return store, slot, {**mem, "mob": mob, "sscore": sscore}\n# EVOLVE-BLOCK-END\n\n\n', '"""Energy-pumping resonance search ("resonator").\n\nIdea: physics bugs (runaway integration, tunnelling through thin/soft geometry, shapes launched out of the arena) all\nrequire *energy*, and energy is injected by driving actuators in phase with the level\'s own oscillation, not by\nrandom button mashing.\n(1) act() runs five structured drives instead of random actions: motor square waves at a per-worker period, thruster\n    holds, thruster pulse trains, a velocity-feedback pump (push the motor in whichever direction the dynamic\n    centroid is already moving -- the classic playground-swing resonance), and a thruster/motor interleave. Each\n    worker re-rolls its drive after a restore, after an epoch, or when its energy plateaus.\n(2) The archive is an energy *ladder*: slots are partitioned into NB bands by log speed and each band keeps a rotating\n    set of states, so the archive can never collapse onto one state and always retains a staircase of increasingly\n    energetic configurations.\n(3) restore() is an explicit hill-climb: workers jump to the highest occupied band (or a random band for diversity)\n    whenever their own energy record has not improved for PATIENCE steps, so every restore restarts pumping from the\n    fastest state found so far. Repeated pump-and-checkpoint cycles multiply speed geometrically.\n"""\nimport jax, jax.numpy as jnp\n\n# EVOLVE-BLOCK-START\nNB = 8            # number of log-speed bands in the ladder archive\nBPO = 1.6         # bands per octave of log2(1 + energy)\nP_LADDER = 0.05   # baseline per-step restore probability\nPATIENCE = 30     # steps without a personal energy record before forcing a restore\nTOP_FRAC = 0.55   # probability of restoring from the highest occupied band (else a random band)\nP_STORE = 0.10    # probability of storing a non-record state (keeps bands fresh)\nEPOCH = 48        # steps before a worker re-rolls its drive pattern\nPERIODS = (2, 3, 4, 6, 8, 12)\nN_MODE = 5        # square wave / thruster hold / thruster pulse / velocity-feedback pump / interleave\nVEL_W = 0.4       # weight of the centroid speed in the energy score (on top of dyn_max_speed)\n\n\ndef _energy(X):\n    """Kinetic-energy proxy: peak movable-shape speed plus centroid speed. X: (N, F)."""\n    return X[:, 4] + VEL_W * jnp.sqrt(X[:, 2] ** 2 + X[:, 3] ** 2)\n\n\ndef _roll(mem, key, B):\n    """Draw a fresh drive pattern (mode, motor, thruster, period, feedback axis, direction bit) per worker."""\n    k1, k2, k3, k4, k5, k6 = jax.random.split(key, 6)\n    u = jax.random.normal(k5, (B, 2), jnp.float32)\n    return (jax.random.randint(k1, (B,), 0, N_MODE),\n            2 * jax.random.randint(k2, (B,), 0, mem["nm"]),\n            mem["thr"][jax.random.randint(k3, (B,), 0, mem["thr"].shape[0])],\n            mem["per"][jax.random.randint(k4, (B,), 0, mem["per"].shape[0])],\n            u / (jnp.linalg.norm(u, axis=-1, keepdims=True) + 1e-6),\n            jax.random.randint(k6, (B,), 0, 2))\n\n\ndef init(rng, F, n_act, K, B):\n    nm = max(1, (n_act - 3) // 2)               # motor bindings: n_act = 2*NM + 1 (no-op) + NT thrusters\n    noop = 2 * nm\n    thr = [noop + 1 + t for t in range(max(0, n_act - 1 - 2 * nm))] or [noop]\n    S = max(1, K // NB)\n    mem = {"n_act": jnp.int32(n_act), "nm": jnp.int32(nm), "noop": jnp.int32(noop),\n           "thr": jnp.array(thr, jnp.int32), "per": jnp.array(PERIODS, jnp.int32),\n           "S": jnp.int32(S), "K": jnp.int32(K),\n           "ptr": jnp.zeros(NB, jnp.int32), "cnt": jnp.zeros(NB, jnp.int32),\n           "bbest": jnp.full(NB, -1e6, jnp.float32),\n           "ph": jnp.zeros(B, jnp.int32), "pb": jnp.full((B,), -1e6, jnp.float32),\n           "stall": jnp.zeros(B, jnp.int32), "just": jnp.zeros(B, bool)}\n    mode, mot, th, per, u, d = _roll(mem, rng, B)\n    mem.update({"mode": mode, "mot": mot, "tha": th, "prd": per, "u": u, "dbit": d})\n    return mem\n\n\ndef restore(mem, feats, arch_feats, arch_valid, arch_visits, rng):\n    B = feats.shape[0]; K = arch_valid.shape[0]; k1, k2, k3, k4 = jax.random.split(rng, 4)\n    hb = jnp.argmax(jnp.where(mem["cnt"] > 0, jnp.arange(NB), -1))          # highest occupied band\n    band = jnp.where(jax.random.uniform(k1, (B,)) < TOP_FRAC, hb, jax.random.randint(k2, (B,), 0, NB))\n    n = jnp.maximum(jnp.minimum(mem["cnt"][band], mem["S"]), 1)\n    slot = jnp.clip(band * mem["S"] + jax.random.randint(k3, (B,), 0, 1 << 20) % n, 0, K - 1)\n    do = ((jax.random.uniform(k4, (B,)) < P_LADDER) | (mem["stall"] > PATIENCE)) & arch_valid.any()\n    return do, slot, {**mem, "just": do, "stall": jnp.where(do, 0, mem["stall"]),\n                      "pb": jnp.where(do, jnp.float32(-1e6), mem["pb"])}\n\n\ndef act(mem, feats, obs, rng):\n    B = feats.shape[0]; k1, k2, k3 = jax.random.split(rng, 3)\n    E = _energy(feats)\n    rec = E > mem["pb"] + 1e-3\n    stall = jnp.where(rec, 0, mem["stall"] + 1)\n    reroll = mem["just"] | (mem["ph"] >= EPOCH) | (stall > PATIENCE)\n    mode, mot, tha, prd, u, dbit = _roll(mem, k1, B)\n    mode = jnp.where(reroll, mode, mem["mode"]); mot = jnp.where(reroll, mot, mem["mot"])\n    tha = jnp.where(reroll, tha, mem["tha"]); prd = jnp.where(reroll, prd, mem["prd"])\n    u = jnp.where(reroll[:, None], u, mem["u"]); dbit = jnp.where(reroll, dbit, mem["dbit"])\n    ph = jnp.where(reroll, 0, mem["ph"])\n    half = (ph // prd) % 2\n    pump = (feats[:, 2] * u[:, 0] + feats[:, 3] * u[:, 1] < 0).astype(jnp.int32)\n    a = jnp.where(mode == 0, mot + half,\n        jnp.where(mode == 1, tha,\n        jnp.where(mode == 2, jnp.where(half == 0, tha, mem["noop"]),\n        jnp.where(mode == 3, mot + pump,\n                  jnp.where(ph % 2 == 0, tha, mot + dbit)))))\n    a = jnp.where(jax.random.uniform(k2, (B,)) < 0.05, jax.random.randint(k3, (B,), 0, mem["n_act"]), a)\n    return a.astype(jnp.int32), {**mem, "mode": mode, "mot": mot, "tha": tha, "prd": prd, "u": u, "dbit": dbit,\n                                 "ph": ph + 1, "pb": jnp.maximum(mem["pb"], E),\n                                 "stall": jnp.where(reroll, 0, stall), "just": jnp.zeros(B, bool)}\n\n\ndef archive(mem, feats, done, arch_feats, arch_valid, rng):\n    B = feats.shape[0]; K = arch_valid.shape[0]\n    E = _energy(feats)\n    band = jnp.clip((jnp.log2(1.0 + jnp.maximum(E, 0.0)) * BPO).astype(jnp.int32), 0, NB - 1)\n    rank = ((band[:, None] == band[None, :]) & (jnp.arange(B)[:, None] > jnp.arange(B)[None, :])).sum(-1)\n    slot = jnp.clip(band * mem["S"] + (mem["ptr"][band] + rank) % mem["S"], 0, K - 1)\n    store = (~done) & ((mem["cnt"][band] < mem["S"]) | (E > mem["bbest"][band] - 0.02)\n                       | (jax.random.uniform(rng, (B,)) < P_STORE))\n    inc = store.astype(jnp.int32)\n    ptr = mem["ptr"].at[band].add(inc)\n    cnt = jnp.minimum(mem["cnt"].at[band].add(inc), mem["S"])\n    bbest = mem["bbest"].at[band].max(jnp.where(store, E, jnp.float32(-1e6)))\n    return store, slot, {**mem, "ptr": ptr, "cnt": cnt, "bbest": bbest}\n# EVOLVE-BLOCK-END\n\n\n', '"""Systematic (mover, target) visitation with restore-and-approach ("targetcycle").\n\nSHORTCUT, TUNNEL and DISARMED are all "shape A must end up on shape B" bugs, so this program treats testing as a\ncovering problem over the (moving shape, non-wall target shape) grid instead of a search over action sequences.\n(1) The contact-flag tail of `feats` is decoded back into shape pairs -- the engine\'s pair lists are a deterministic\n    function of the shape counts -- giving an online "which pair has ever touched" matrix. Each worker takes the\n    least-attempted *untouched* valid pair, mildly favouring goal-coloured or immobile-neutral targets and green\n    movers, so effort drains away from pairs that already collide; a de-solidified obstacle can never register a\n    contact, so it keeps drawing attempts.\n(2) act() is a per-worker bandit over actions whose reward is the best closing achieved during a whole hold (start\n    distance minus the minimum distance reached) plus a bonus for touching the pair, which credits ballistic\n    launches that a greedy per-step closing rate would reject.\n(3) The archive keeps the closest approach ever recorded for each (mover class, target) coordinate plus a hash-cell\n    coverage pool; a worker that stops closing jumps back to its coordinate\'s closest-approach checkpoint and\n    re-attacks, and gives up on the pair after a few failed attempts.\n"""\nimport jax, jax.numpy as jnp\n\n# EVOLVE-BLOCK-START\nHOLD = 9            # steps one action is held; the bandit is scored on the whole hold\nLONG_P = 0.25       # fraction of holds that are extended (energy / long launches)\nLONG_M = 3          # multiplier for a long hold\nLR = 0.35           # EMA rate of the per-worker action -> hold-progress table\nINV_T = 3.0         # inverse temperature on that table\nUCB_C = 0.5         # optimism bonus for rarely tried actions\nEPS_RAND = 0.15     # uniform-random action rate\nTOUCH_BONUS = 1.5   # bandit reward for actually contacting the assigned pair during a hold\nSTALL_T = 3         # failed holds before jumping back to the pair\'s best approach\nGIVEUP = 3          # failed approach attempts before the worker takes a new pair\nP_BASE = 0.02       # baseline per-step restore probability (coverage pool)\nBIG = 12.0          # distance cap / "unreachable" value\nMOB_THR = 0.05      # speed above which a shape index counts as a mover (learned online)\nW_GOAL = 0.8        # pair priority: target carries the goal colour\nW_STAT = 0.8        # pair priority: target is an immobile neutral obstacle\nW_GREEN = 0.6       # pair priority: mover is a green (agent-side) shape\nSOLVED_W = 2.5      # priority penalty for a pair that has already been seen to touch\nCNT_W = 1.2         # weight of the round-robin attempt counter in pair selection\nGSC = 0.7           # gumbel scale on pair selection\nREC_INFL = 0.001    # per-step inflation of the closest-approach records (keeps slots replaceable)\nMARGIN = 0.02       # improvement required to overwrite a record slot\nELITE_B = 0.3       # restore-logit bonus for the closest-approach slots\nBITS = 11           # hash bits for the coverage pool\nCELL_RES = 0.5      # coarse grid resolution of the coverage cells\nCELL_DIMS = (0, 1, 2, 3, 5, 6, 9, 10)\nNW = 4              # boundary walls: the first 4 polygons\n\n\ndef _idx(F):\n    """Per-shape blocks and the contact-flag -> shape-pair map, from the (size-unique) feature width."""\n    sols = [(p, c) for p in range(4, 41) for c in range(0, 41)\n            if 11 + 7 * p + 6 * c + (p * (p - 1) // 2 - 6) + c * p + c * (c - 1) // 2 == F]\n    if len(sols) != 1:\n        return dict(use=0.0, N=1, px=[0], py=[1], vx=[2], vy=[3], ai=[8], ri=[8], wall=[1.0],\n                    cbase=0, nf=1, fidx=[[-1]])\n    Np, Nc = sols[0]\n    P = 11; PV = P + 2 * Np; PA = P + 5 * Np; PL = P + 6 * Np\n    C = P + 7 * Np; CV = C + 2 * Nc; CA = C + 4 * Nc; CL = CA + Nc\n    pp = [(i, j) for i in range(Np) for j in range(Np) if i < j and not (i < NW and j < NW)]\n    cp = [(Np + c, r) for c in range(Nc) for r in range(Np)]\n    cc = [(Np + i, Np + j) for i in range(Nc) for j in range(Nc) if i < j]\n    prs = pp + cp + cc\n    N = Np + Nc\n    fidx = [[-1] * N for _ in range(N)]\n    for k, (i, j) in enumerate(prs):\n        fidx[i][j] = k; fidx[j][i] = k\n    return dict(use=1.0, N=N, cbase=CL + Nc, nf=len(prs), fidx=fidx,\n                px=[P + 2 * i for i in range(Np)] + [C + 2 * i for i in range(Nc)],\n                py=[P + 2 * i + 1 for i in range(Np)] + [C + 2 * i + 1 for i in range(Nc)],\n                vx=[PV + 2 * i for i in range(Np)] + [CV + 2 * i for i in range(Nc)],\n                vy=[PV + 2 * i + 1 for i in range(Np)] + [CV + 2 * i + 1 for i in range(Nc)],\n                ai=[PA + i for i in range(Np)] + [CA + i for i in range(Nc)],\n                ri=[PL + i for i in range(Np)] + [CL + i for i in range(Nc)],\n                wall=[1.0 if i < NW else 0.0 for i in range(Np)] + [0.0] * Nc)\n\n\ndef _geo(mem, X):\n    """Centre-to-centre distances (R,N,N) plus mover / target / green masks (R,N) for the rows of X."""\n    px = X[:, mem["px"]]; py = X[:, mem["py"]]\n    act = X[:, mem["ai"]] > 0.5\n    role = X[:, mem["ri"]]\n    d = jnp.sqrt((px[:, :, None] - px[:, None, :]) ** 2 + (py[:, :, None] - py[:, None, :]) ** 2 + 1e-9)\n    nowall = mem["wall"] < 0.5\n    known = jnp.where(mem["mob"].max() > MOB_THR, mem["mob"] > MOB_THR, jnp.ones_like(mem["mob"], bool))\n    green = act & (jnp.abs(role - 1.0) < 0.5)\n    return d, act & nowall[None, :] & known[None, :], act & nowall[None, :], green\n\n\ndef _dmin(mem, X):\n    """(R, 2, N): closest approach of any non-green / green mover to each target shape."""\n    d, mover, tgt, green = _geo(mem, X)\n    N = d.shape[-1]\n    d = jnp.where(jnp.eye(N, dtype=bool)[None], jnp.inf, d)\n    cls = jnp.stack([mover & ~green, mover & green], axis=1)\n    dd = jnp.where(cls[:, :, :, None], d[:, None, :, :], jnp.inf)\n    dd = jnp.where(tgt[:, None, None, :], dd, jnp.inf)\n    return jnp.minimum(jnp.min(dd, axis=2), BIG)\n\n\ndef _cell(mem, feats):\n    x = jnp.round(feats[:, jnp.array(CELL_DIMS)] / CELL_RES) * CELL_RES\n    return ((x @ mem["proj"] > 0) * (2 ** jnp.arange(BITS))).sum(-1).astype(jnp.int32)\n\n\ndef init(rng, F, n_act, K, B):\n    ix = _idx(F); N = ix["N"]; E = min(2 * N, max(2, K // 2)); KC = max(1, K - E)\n    return {"n_act": jnp.int32(n_act), "N": jnp.int32(N), "E": jnp.int32(E), "KC": jnp.int32(KC),\n            "use": jnp.float32(ix["use"]), "wall": jnp.array(ix["wall"], jnp.float32),\n            "px": jnp.array(ix["px"], jnp.int32), "py": jnp.array(ix["py"], jnp.int32),\n            "vx": jnp.array(ix["vx"], jnp.int32), "vy": jnp.array(ix["vy"], jnp.int32),\n            "ai": jnp.array(ix["ai"], jnp.int32), "ri": jnp.array(ix["ri"], jnp.int32),\n            "fidx": jnp.array(ix["fidx"], jnp.int32), "cbase": jnp.int32(ix["cbase"]),\n            "cf": jnp.array(list(range(ix["cbase"], ix["cbase"] + ix["nf"])), jnp.int32),\n            "tflag": jnp.zeros(ix["nf"], jnp.float32),\n            "mob": jnp.zeros(N, jnp.float32), "pcnt": jnp.zeros(N * N, jnp.float32),\n            "rec": jnp.full(E, BIG, jnp.float32),\n            "mov": jnp.zeros(B, jnp.int32), "tgt": jnp.zeros(B, jnp.int32), "cls": jnp.zeros(B, jnp.int32),\n            "Q": jnp.zeros((B, n_act), jnp.float32), "Qn": jnp.zeros((B, n_act), jnp.float32),\n            "cur": jnp.zeros(B, jnp.int32), "left": jnp.zeros(B, jnp.int32),\n            "d0": jnp.full(B, BIG, jnp.float32), "hmin": jnp.full(B, BIG, jnp.float32),\n            "hcon": jnp.zeros(B, jnp.float32), "bd": jnp.full(B, BIG, jnp.float32),\n            "stall": jnp.zeros(B, jnp.int32), "tries": jnp.full(B, GIVEUP + 1, jnp.int32),\n            "fresh": jnp.ones(B, bool), "jump": jnp.zeros(B, bool),\n            "proj": jax.random.normal(rng, (len(CELL_DIMS), BITS)),\n            "cell_slot": jnp.full(2 ** BITS, -1, jnp.int32), "next_free": jnp.int32(0)}\n\n\ndef restore(mem, feats, arch_feats, arch_valid, arch_visits, rng):\n    B = feats.shape[0]; K = arch_valid.shape[0]; k1, k2 = jax.random.split(rng)\n    e_slot = jnp.clip(mem["cls"] * mem["N"] + mem["tgt"], 0, mem["E"] - 1)\n    logits = jnp.where(arch_valid, -0.5 * jnp.log1p(arch_visits.astype(jnp.float32))\n                       + ELITE_B * (jnp.arange(K) < mem["E"]).astype(jnp.float32), -1e9)\n    cov = jnp.argmax(logits[None, :] + jax.random.gumbel(k2, (B, K), jnp.float32), axis=1)\n    jump = mem["jump"] & arch_valid[e_slot]\n    slot = jnp.where(jump, e_slot, cov)\n    do = (jump | (jax.random.uniform(k1, (B,)) < P_BASE)) & arch_valid.any()\n    return do, slot, {**mem, "fresh": do, "jump": jnp.zeros(B, bool),\n                      "stall": jnp.where(mem["jump"], 0, mem["stall"]),\n                      "tries": jnp.where(mem["jump"], mem["tries"] + 1, mem["tries"]),\n                      "bd": jnp.where(do, jnp.float32(BIG), mem["bd"]),\n                      "left": jnp.where(do, 0, mem["left"])}\n\n\ndef act(mem, feats, obs, rng):\n    B = feats.shape[0]; N = mem["N"]; ar = jnp.arange(B)\n    k1, k2, k3, k4, k5 = jax.random.split(rng, 5)\n    d, mover, tgt_ok, green = _geo(mem, feats)\n    dp = jnp.minimum(d[ar, mem["mov"], mem["tgt"]], BIG)\n    fl = mem["fidx"][mem["mov"], mem["tgt"]]\n    con = jnp.where(fl >= 0, feats[:, mem["cf"]][ar, jnp.maximum(fl, 0)], 0.0)\n    hmin = jnp.minimum(mem["hmin"], dp); hcon = jnp.maximum(mem["hcon"], con)\n    end = mem["left"] <= 0\n    # ---- score the finished hold: best closing achieved + contact bonus ----\n    r = (mem["d0"] - hmin) + TOUCH_BONUS * hcon\n    oh = (jnp.arange(mem["Q"].shape[1]) == mem["cur"][:, None]).astype(jnp.float32)\n    upd = end & (~mem["fresh"])\n    Q = jnp.where(upd[:, None], mem["Q"] + LR * oh * (r[:, None] - mem["Q"]), mem["Q"])\n    Qn = mem["Qn"] + upd[:, None] * oh\n    good = r > 1e-3\n    stall = jnp.where(upd & ~good, mem["stall"] + 1, jnp.where(upd, 0, mem["stall"]))\n    bd = jnp.minimum(mem["bd"], dp)\n    switch = mem["tries"] > GIVEUP\n    # ---- least-attempted, still-untouched valid (mover, target) pair ----\n    mv_b = mover.any(0); tg_b = tgt_ok.any(0); gr_b = green.any(0)\n    role_b = feats[:, mem["ri"]].max(0)\n    solved = jnp.where(mem["fidx"] >= 0, mem["tflag"][jnp.maximum(mem["fidx"], 0)], 1e3) > 0.5\n    prio_t = W_GOAL * (jnp.abs(role_b - 2.0) < 0.5) + W_STAT * ((jnp.abs(role_b) < 0.5) & (mem["mob"] <= MOB_THR))\n    prio = (W_GREEN * gr_b[:, None].astype(jnp.float32) + prio_t[None, :]\n            - SOLVED_W * solved.astype(jnp.float32) - CNT_W * jnp.log1p(mem["pcnt"].reshape(solved.shape)))\n    valid = mv_b[:, None] & tg_b[None, :] & ~jnp.eye(role_b.shape[0], dtype=bool)\n    sc = jnp.where(valid, prio, -1e9).reshape(-1)\n    pick = jnp.argmax(sc[None, :] + GSC * jax.random.gumbel(k1, (B, sc.shape[0]), jnp.float32), axis=1)\n    mov = jnp.where(switch, pick // N, mem["mov"]); tgt = jnp.where(switch, pick % N, mem["tgt"])\n    cls = jnp.where(switch, gr_b[mov].astype(jnp.int32), mem["cls"])\n    pcnt = mem["pcnt"].at[jnp.where(switch, pick, 0)].add(jnp.where(switch, 1.0, 0.0))\n    Q = jnp.where(switch[:, None], 0.0, Q); Qn = jnp.where(switch[:, None], 0.0, Qn)\n    stall = jnp.where(switch, 0, stall); tries = jnp.where(switch, 0, mem["tries"])\n    bd = jnp.where(switch, jnp.float32(BIG), bd)\n    dp = jnp.where(switch, jnp.minimum(d[ar, mov, tgt], BIG), dp)\n    # ---- action for the next hold ----\n    new = end | switch\n    score = INV_T * Q + UCB_C * jax.lax.rsqrt(1.0 + Qn)\n    a_g = jnp.argmax(score + jax.random.gumbel(k2, score.shape, jnp.float32), axis=1)\n    a_r = jax.random.randint(k3, (B,), 0, mem["n_act"])\n    a_new = jnp.where(jax.random.uniform(k4, (B,)) < EPS_RAND, a_r, a_g)\n    L = jnp.where(jax.random.uniform(k5, (B,)) < LONG_P, HOLD * LONG_M, HOLD)\n    cur = jnp.where(new, a_new, mem["cur"]).astype(jnp.int32)\n    left = jnp.where(new, L, mem["left"]) - 1\n    return cur, {**mem, "Q": Q, "Qn": Qn, "cur": cur, "left": left, "mov": mov, "tgt": tgt, "cls": cls,\n                 "pcnt": pcnt, "bd": bd, "stall": stall, "tries": tries, "fresh": jnp.zeros(B, bool),\n                 "d0": jnp.where(new, dp, mem["d0"]), "hmin": jnp.where(new, dp, hmin),\n                 "hcon": jnp.where(new, 0.0, hcon), "jump": stall > STALL_T}\n\n\ndef archive(mem, feats, done, arch_feats, arch_valid, rng):\n    B = feats.shape[0]\n    spd = jnp.sqrt(feats[:, mem["vx"]] ** 2 + feats[:, mem["vy"]] ** 2) * (feats[:, mem["ai"]] > 0.5)\n    mob = jnp.maximum(mem["mob"], spd.max(0) * mem["use"])\n    tflag = mem["tflag"] + feats[:, mem["cf"]].sum(0)\n    dsc = _dmin({**mem, "mob": mob}, feats).reshape(B, -1)[:, :mem["rec"].shape[0]]\n    rec = jnp.minimum(mem["rec"] + REC_INFL, BIG)\n    imp = rec[None, :] - dsc\n    j = jnp.argmax(imp + 0.35 * jax.random.gumbel(rng, imp.shape, jnp.float32), axis=1)\n    gain = imp[jnp.arange(B), j]\n    store_e = (gain > MARGIN) & (~done) & (mem["use"] > 0.5)\n    cell = _cell(mem, feats)\n    is_new = (mem["cell_slot"][cell] < 0) & (~done) & (~store_e)\n    cov = mem["E"] + (mem["next_free"] + jnp.cumsum(is_new) - 1) % mem["KC"]\n    slot = jnp.where(store_e, j, cov)\n    cell_slot = mem["cell_slot"].at[jnp.where(is_new, cell, 0)].set(jnp.where(is_new, cov, mem["cell_slot"][0]))\n    rec = rec.at[jnp.where(store_e, j, 0)].min(jnp.where(store_e, dsc[jnp.arange(B), j], jnp.inf))\n    return store_e | is_new, slot, {**mem, "mob": mob, "tflag": tflag, "rec": rec, "cell_slot": cell_slot,\n                                    "next_free": (mem["next_free"] + is_new.sum()) % mem["KC"]}\n# EVOLVE-BLOCK-END\n\n\n', '"""Per-target distance ladders swept by a macro library ("pairladder").\n\nA macro sweep explores well but its novelty frontier has no notion that a tester\'s job is to bring shapes *together*,\nso here the frontier metric becomes the set of (mover class, target shape) centre distances.\n(1) Half the archive is one ladder per coordinate j = (class in {non-green, green}, non-wall target); rung b holds the\n    best state whose class-to-target distance falls in the b-th log band, making that half a staircase of ever-closer\n    approaches to every shape. The other half stays a plain novelty frontier, supplying the breadth a ladder lacks.\n(2) act() replays a deterministic macro library -- sustained motor holds, fast and slow reversals, thruster holds and\n    pulse trains, all-motor sweeps, settle, short bursts -- the coherent input programs a human tester tries first.\n(3) restore() fires exactly when a macro finishes: with probability LAD_P the worker moves to the coordinate whose\n    ladder is *least descended* (damped by a round-robin counter so every shape keeps getting attempts) and restarts\n    from one of its occupied rungs, preferring low rungs that have been expanded least; otherwise it restarts from the\n    least-expanded novelty node. Closing a gap by one band creates a new rung to launch from next time.\n"""\nimport jax, jax.numpy as jnp\n\n# EVOLVE-BLOCK-START\nMACRO_L = 18        # length of a full macro\nSHORT_L = 6         # length of the short-burst macros\nLAD_P = 0.6         # probability that a macro is launched from a ladder rung (else from the novelty frontier)\nRUNG_W = 0.8        # preference for low (close) rungs when choosing where on a ladder to restart\nVIS_W = 0.7         # least-expanded preference among rungs / frontier nodes\nNOV_EPS = 0.30      # novelty radius (scaled feature units) required to store a frontier state\nNOV_DIMS = (0, 1, 2, 3, 4, 5, 6, 9, 10)\nNOV_SCALE = (1.0, 1.0, 0.25, 0.25, 0.25, 1.0, 1.0, 1.0, 1.0)\nP_STORE = 0.02      # probability of refreshing a rung with a non-record state\nMARGIN = 0.01       # improvement required to overwrite a rung\nBAND_W = 0.5        # priority for coordinates whose ladder has not descended far\nCNT_W = 1.5         # round-robin damping of that priority\nJGS = 1.0           # gumbel scale on the coordinate choice\nDMAX = 8.0          # distance cap used to lay out the ladder bands\nEPS_RAND = 0.04     # tiny action noise, breaks symmetry between workers on identical checkpoints\nMOB_THR = 0.05      # speed above which a shape index counts as a mover (learned online)\nNW = 4              # boundary walls: the first 4 polygons\n\n\ndef _idx(F):\n    """Per-shape position / velocity / active / role blocks from the (size-unique) feature width."""\n    sols = [(p, c) for p in range(4, 41) for c in range(0, 41)\n            if 11 + 7 * p + 6 * c + (p * (p - 1) // 2 - 6) + c * p + c * (c - 1) // 2 == F]\n    if len(sols) != 1:\n        return dict(use=0.0, N=1, px=[0], py=[1], vx=[2], vy=[3], ai=[8], ri=[8], wall=[1.0])\n    Np, Nc = sols[0]\n    P = 11; PV = P + 2 * Np; PA = P + 5 * Np; PL = P + 6 * Np\n    C = P + 7 * Np; CV = C + 2 * Nc; CA = C + 4 * Nc; CL = CA + Nc\n    return dict(use=1.0, N=Np + Nc,\n                px=[P + 2 * i for i in range(Np)] + [C + 2 * i for i in range(Nc)],\n                py=[P + 2 * i + 1 for i in range(Np)] + [C + 2 * i + 1 for i in range(Nc)],\n                vx=[PV + 2 * i for i in range(Np)] + [CV + 2 * i for i in range(Nc)],\n                vy=[PV + 2 * i + 1 for i in range(Np)] + [CV + 2 * i + 1 for i in range(Nc)],\n                ai=[PA + i for i in range(Np)] + [CA + i for i in range(Nc)],\n                ri=[PL + i for i in range(Np)] + [CL + i for i in range(Nc)],\n                wall=[1.0 if i < NW else 0.0 for i in range(Np)] + [0.0] * Nc)\n\n\ndef _macros(n_act):\n    """Deterministic macro library: (M, MACRO_L) action table + per-macro length."""\n    nm = max(1, (n_act - 3) // 2); noop = 2 * nm\n    thr = [noop + 1 + t for t in range(max(0, n_act - 1 - 2 * nm))] or [noop]\n    ms = []\n    def add(pat, L): ms.append(([int(pat[i % len(pat)]) for i in range(MACRO_L)], L))\n    for m in range(nm):\n        add([2 * m], MACRO_L); add([2 * m + 1], MACRO_L)\n        add([2 * m, 2 * m, 2 * m + 1, 2 * m + 1], MACRO_L)\n        add([2 * m] * 5 + [2 * m + 1] * 5, MACRO_L)\n    for t in thr:\n        add([t], MACRO_L); add([t, t, noop, noop], MACRO_L)\n    for m in range(nm):\n        add([thr[m % len(thr)], 2 * m], MACRO_L)\n    add([2 * m for m in range(nm)], MACRO_L); add([2 * m + 1 for m in range(nm)], MACRO_L)\n    add([noop], MACRO_L)\n    for m in range(nm):\n        add([2 * m], SHORT_L); add([2 * m + 1], SHORT_L)\n    add([thr[0], noop], SHORT_L)\n    return [p for p, _ in ms], [L for _, L in ms]\n\n\ndef _known(mem):\n    return jnp.where(mem["mob"].max() > MOB_THR, mem["mob"] > MOB_THR, jnp.ones_like(mem["mob"], bool))\n\n\ndef _dsc(mem, X):\n    """(R, 2N): closest approach of any non-green / green mover to each target shape, flattened."""\n    px = X[:, mem["px"]]; py = X[:, mem["py"]]\n    act = X[:, mem["ai"]] > 0.5\n    role = X[:, mem["ri"]]\n    N = px.shape[1]\n    d = jnp.sqrt((px[:, :, None] - px[:, None, :]) ** 2 + (py[:, :, None] - py[:, None, :]) ** 2 + 1e-9)\n    d = jnp.where(jnp.eye(N, dtype=bool)[None], jnp.inf, d)\n    nowall = mem["wall"] < 0.5\n    green = act & (jnp.abs(role - 1.0) < 0.5)\n    mover = act & nowall[None, :] & _known(mem)[None, :]\n    cls = jnp.stack([mover & ~green, mover & green], axis=1)                    # (R,2,N)\n    dd = jnp.where(cls[:, :, :, None], d[:, None, :, :], jnp.inf)\n    dd = jnp.where((act & nowall[None, :])[:, None, None, :], dd, jnp.inf)\n    return jnp.minimum(jnp.min(dd, axis=2), DMAX).reshape(px.shape[0], 2 * N)\n\n\ndef _ok(mem, X):\n    """(2N,) coordinates worth working on: an existing mover class and an active non-wall target."""\n    act = (X[:, mem["ai"]] > 0.5).any(0)\n    role = X[:, mem["ri"]].max(0)\n    green = act & (jnp.abs(role - 1.0) < 0.5)\n    mover = act & (mem["wall"] < 0.5) & _known(mem)\n    tgt = act & (mem["wall"] < 0.5)\n    has = jnp.stack([(mover & ~green).any(), (mover & green).any()])\n    return ((has[:, None] & tgt[None, :]).reshape(-1)) | (mem["use"] < 0.5)\n\n\ndef _band(mem, d):\n    S = mem["occ"].shape[1]\n    return jnp.clip((mem["bpo"] * jnp.log2(1.0 + jnp.maximum(d, 0.0))).astype(jnp.int32), 0, S - 1)\n\n\ndef init(rng, F, n_act, K, B):\n    import math\n    ix = _idx(F); N = ix["N"]; J = 2 * N\n    S = max(2, (K // 2) // J); tab, ln = _macros(n_act); M = len(tab); KL = min(J * S, K - 1)\n    return {"n_act": jnp.int32(n_act), "M": jnp.int32(M), "use": jnp.float32(ix["use"]),\n            "bpo": jnp.float32((S - 1) / math.log2(1.0 + DMAX)),\n            "wall": jnp.array(ix["wall"], jnp.float32),\n            "px": jnp.array(ix["px"], jnp.int32), "py": jnp.array(ix["py"], jnp.int32),\n            "vx": jnp.array(ix["vx"], jnp.int32), "vy": jnp.array(ix["vy"], jnp.int32),\n            "ai": jnp.array(ix["ai"], jnp.int32), "ri": jnp.array(ix["ri"], jnp.int32),\n            "mob": jnp.zeros(N, jnp.float32), "KL": jnp.int32(KL), "KN": jnp.int32(max(1, K - KL)),\n            "nov": jnp.array(NOV_DIMS, jnp.int32), "sc": jnp.array(NOV_SCALE, jnp.float32),\n            "next_free": jnp.int32(0),\n            "best": jnp.full((J, S), jnp.float32(1e6)), "occ": jnp.zeros((J, S), bool),\n            "table": jnp.array(tab, jnp.int32), "mlen": jnp.array(ln, jnp.int32),\n            "jcnt": jnp.zeros(J, jnp.float32),\n            "j": jnp.arange(B, dtype=jnp.int32) % jnp.int32(J), "mid": jnp.arange(B, dtype=jnp.int32) % jnp.int32(M),\n            "ph": jnp.zeros(B, jnp.int32), "at_end": jnp.zeros(B, bool)}\n\n\ndef restore(mem, feats, arch_feats, arch_valid, arch_visits, rng):\n    B = feats.shape[0]; K = arch_valid.shape[0]; J, S = mem["occ"].shape\n    k1, k2, k3, k4 = jax.random.split(rng, 4)\n    ok = _ok(mem, feats)\n    lowb = jnp.argmin(jnp.where(mem["occ"], jnp.arange(S)[None, :], S + 10), axis=1)\n    lowb = jnp.where(mem["occ"].any(1), lowb, S).astype(jnp.float32)   # how far this ladder still has to descend\n    jsc = jnp.where(ok, BAND_W * lowb - CNT_W * jnp.log1p(mem["jcnt"]), -1e9)\n    jp = jnp.argmax(jsc[None, :] + JGS * jax.random.gumbel(k1, (B, J), jnp.float32), axis=1)\n    jn = jnp.where(mem["at_end"], jp, mem["j"])\n    jcnt = mem["jcnt"].at[jnp.where(mem["at_end"], jp, 0)].add(jnp.where(mem["at_end"], 1.0, 0.0))\n    # ---- pick a rung of this coordinate\'s ladder: low band, least expanded ----\n    idx = jnp.clip(jn[:, None] * S + jnp.arange(S)[None, :], 0, K - 1)\n    occ = mem["occ"][jn]\n    rsc = jnp.where(occ, -RUNG_W * jnp.arange(S)[None, :]\n                    - VIS_W * jnp.log1p(arch_visits[idx].astype(jnp.float32)), -1e9)\n    band = jnp.argmax(rsc + jax.random.gumbel(k2, (B, S), jnp.float32), axis=1)\n    lad_slot = jnp.clip(jn * S + band, 0, K - 1)\n    # ---- or the least-expanded novelty frontier node ----\n    fsc = jnp.where(arch_valid & (jnp.arange(K) >= mem["KL"]),\n                    -VIS_W * jnp.log1p(arch_visits.astype(jnp.float32)), -1e9)\n    nov_slot = jnp.argmax(fsc[None, :] + jax.random.gumbel(k3, (B, K), jnp.float32), axis=1)\n    use_lad = (jax.random.uniform(k4, (B,)) < LAD_P) & occ.any(1)\n    slot = jnp.where(use_lad, lad_slot, nov_slot)\n    do = mem["at_end"] & (use_lad | (fsc.max() > -1e8)) & arch_valid.any()\n    return do, slot, {**mem, "j": jn, "jcnt": jcnt, "at_end": jnp.zeros(B, bool)}\n\n\ndef act(mem, feats, obs, rng):\n    B = feats.shape[0]; k1, k2 = jax.random.split(rng)\n    ph = jnp.clip(mem["ph"], 0, mem["table"].shape[1] - 1)\n    a = mem["table"][mem["mid"], ph]\n    a = jnp.where(jax.random.uniform(k1, (B,)) < EPS_RAND, jax.random.randint(k2, (B,), 0, mem["n_act"]), a)\n    nxt = mem["ph"] + 1\n    end = nxt >= mem["mlen"][mem["mid"]]\n    return a.astype(jnp.int32), {**mem, "ph": jnp.where(end, 0, nxt),\n                                 "mid": jnp.where(end, (mem["mid"] + 1) % mem["M"], mem["mid"]), "at_end": end}\n\n\ndef archive(mem, feats, done, arch_feats, arch_valid, rng):\n    B = feats.shape[0]; K = arch_valid.shape[0]; J, S = mem["occ"].shape\n    ar = jnp.arange(B)\n    spd = jnp.sqrt(feats[:, mem["vx"]] ** 2 + feats[:, mem["vy"]] ** 2) * (feats[:, mem["ai"]] > 0.5)\n    mob = jnp.maximum(mem["mob"], spd.max(0) * mem["use"])\n    d = _dsc({**mem, "mob": mob}, feats)[ar, mem["j"]]\n    b = _band({**mem, "mob": mob}, d)\n    lad = (~done) & (mem["use"] > 0.5) & ((d < mem["best"][mem["j"], b] - MARGIN)\n                                          | (~mem["occ"][mem["j"], b])\n                                          | (jax.random.uniform(rng, (B,)) < P_STORE))\n    # novelty frontier: keep a macro endpoint only if it is far from everything already stored\n    x = feats[:, mem["nov"]] * mem["sc"]; y = arch_feats[:, mem["nov"]] * mem["sc"]\n    d2 = ((x[:, None, :] - y[None, :, :]) ** 2).sum(-1)\n    mind = jnp.min(jnp.where(arch_valid[None, :], d2, 1e12), axis=1)\n    nov = (~done) & (~lad) & mem["at_end"] & (mind > NOV_EPS ** 2)\n    nov_slot = mem["KL"] + (mem["next_free"] + jnp.cumsum(nov) - 1) % mem["KN"]\n    slot = jnp.clip(jnp.where(lad, mem["j"] * S + b, nov_slot), 0, K - 1)\n    best = mem["best"].at[jnp.where(lad, mem["j"], 0), jnp.where(lad, b, 0)].min(jnp.where(lad, d, jnp.inf))\n    occ = mem["occ"].at[jnp.where(lad, mem["j"], 0), jnp.where(lad, b, 0)].max(lad)\n    return lad | nov, slot, {**mem, "mob": mob, "best": best, "occ": occ,\n                             "next_free": (mem["next_free"] + nov.sum()) % mem["KN"]}\n\n\n# EVOLVE-BLOCK-END\n\n\n', '"""Goal-biased RRT over the arena with a learned action model and pump/aim extensions ("rrtdrive").\n\nReaching a particular shape that may sit anywhere -- behind an obstacle, on a ledge, across the level -- is a\nmotion-planning problem, so this program grows a rapidly-exploring tree whose nodes are archived states.\n(1) A worker samples a goal: with probability GOAL_BIAS the live position of the least-visited non-wall shape, read\n    from the per-shape position blocks so it tracks moving targets, otherwise a random arena point. It then restores\n    to the archived node whose driven body is nearest that goal -- RRT\'s "extend from the nearest node", with a visit\n    penalty so the tree keeps branching.\n(2) An extension is energy pumping (a resonant motor square wave or a thruster hold, to buy reach and height) followed\n    by aiming: each worker keeps an online per-action model of how the body it drives accelerates and picks the action\n    whose learnt acceleration best aligns with the goal direction. Two bodies are driven in turn, the whole moving\n    assembly and the green shapes, because the green shape is often a passenger rather than the controlled vehicle.\n(3) The archive is a coverage roadmap: an occupancy grid over each body\'s position keeps the fastest state seen in\n    every cell, plus a random reservoir tail, so the tree always has well-spread, momentum-carrying nodes to grow from.\n"""\nimport jax, jax.numpy as jnp\n\n# EVOLVE-BLOCK-START\nGOAL_BIAS = 0.72    # probability that an extension aims at a shape rather than a random arena point\nPUMP_MAX = 26       # longest energy-pumping prefix of an extension\nPUMP_MIN = 0        # shortest (0 = pure aiming)\nAIM_L = 22          # length of the aiming suffix of an extension\nLR = 0.30           # EMA rate of the per-worker action -> body-acceleration model\nMDECAY = 0.6        # how much of the model survives a restore\nTAU = 0.9           # gumbel temperature on the aiming action choice\nEPS_RAND = 0.12     # uniform-random action rate while aiming\nP_BASE = 0.01       # per-step chance of an unscheduled re-plan\nVIS_W = 0.05        # visit penalty in the nearest-node ranking\nNOISE = 0.10        # tie-break noise in the nearest-node ranking\nWORLD = 5.0         # arena side\nP_REF = 0.02        # chance of refreshing a roadmap cell with a non-record state\nP_RES = 0.05        # chance of dropping a state into the random reservoir tail\nQ_EPS = 0.05        # speed margin needed to replace a roadmap cell\nPERIODS = (2, 3, 4, 6, 9, 14)\nNW = 4              # boundary walls: the first 4 polygons\n\n\ndef _idx(F):\n    """Per-shape position / velocity / active / role blocks from the (size-unique) feature width."""\n    sols = [(p, c) for p in range(4, 41) for c in range(0, 41)\n            if 11 + 7 * p + 6 * c + (p * (p - 1) // 2 - 6) + c * p + c * (c - 1) // 2 == F]\n    if len(sols) != 1:\n        return dict(use=0.0, N=1, px=[0], py=[1], vx=[2], vy=[3], ai=[8], ri=[8], wall=[1.0])\n    Np, Nc = sols[0]\n    P = 11; PV = P + 2 * Np; PA = P + 5 * Np; PL = P + 6 * Np\n    C = P + 7 * Np; CV = C + 2 * Nc; CA = C + 4 * Nc; CL = CA + Nc\n    return dict(use=1.0, N=Np + Nc,\n                px=[P + 2 * i for i in range(Np)] + [C + 2 * i for i in range(Nc)],\n                py=[P + 2 * i + 1 for i in range(Np)] + [C + 2 * i + 1 for i in range(Nc)],\n                vx=[PV + 2 * i for i in range(Np)] + [CV + 2 * i for i in range(Nc)],\n                vy=[PV + 2 * i + 1 for i in range(Np)] + [CV + 2 * i + 1 for i in range(Nc)],\n                ai=[PA + i for i in range(Np)] + [CA + i for i in range(Nc)],\n                ri=[PL + i for i in range(Np)] + [CL + i for i in range(Nc)],\n                wall=[1.0 if i < NW else 0.0 for i in range(Np)] + [0.0] * Nc)\n\n\ndef _bodies(mem, X):\n    """Position and velocity of the two driven bodies: (R,2,2) each -- [0] whole assembly, [1] green shapes."""\n    green = ((X[:, mem["ai"]] > 0.5) & (jnp.abs(X[:, mem["ri"]] - 1.0) < 0.5)).astype(jnp.float32)\n    w = green / jnp.maximum(green.sum(-1, keepdims=True), 1.0)\n    gv = jnp.stack([(X[:, mem["vx"]] * w).sum(-1), (X[:, mem["vy"]] * w).sum(-1)], axis=-1)\n    pos = jnp.stack([X[:, 0:2], X[:, 5:7]], axis=1)\n    vel = jnp.stack([X[:, 2:4], gv], axis=1)\n    return pos, vel\n\n\ndef init(rng, F, n_act, K, B):\n    ix = _idx(F); N = ix["N"]\n    R = int(max(4, min(10, (max(K, 8) * 0.5 / 2) ** 0.5))); G = 2 * R * R\n    nm = max(1, (n_act - 3) // 2); noop = 2 * nm\n    thr = [noop + 1 + t for t in range(max(0, n_act - 1 - 2 * nm))] or [noop]\n    k1, k2, k3, k4, k5 = jax.random.split(rng, 5)\n    return {"n_act": jnp.int32(n_act), "N": jnp.int32(N), "R": jnp.int32(R), "G": jnp.int32(G),\n            "nm": jnp.int32(nm), "noop": jnp.int32(noop), "thr": jnp.array(thr, jnp.int32),\n            "per": jnp.array(PERIODS, jnp.int32), "use": jnp.float32(ix["use"]),\n            "wall": jnp.array(ix["wall"], jnp.float32),\n            "px": jnp.array(ix["px"], jnp.int32), "py": jnp.array(ix["py"], jnp.int32),\n            "vx": jnp.array(ix["vx"], jnp.int32), "vy": jnp.array(ix["vy"], jnp.int32),\n            "ai": jnp.array(ix["ai"], jnp.int32), "ri": jnp.array(ix["ri"], jnp.int32),\n            "tcnt": jnp.zeros(N, jnp.float32), "qbest": jnp.full(K, -1e6, jnp.float32),\n            "occ": jnp.zeros(K, bool), "res": jnp.int32(0),\n            "M": jnp.zeros((B, 2, n_act, 2), jnp.float32), "pv": jnp.zeros((B, 2, 2), jnp.float32),\n            "chan": jax.random.randint(k1, (B,), 0, 2), "gsel": jnp.full(B, N, jnp.int32),\n            "gx": jax.random.uniform(k2, (B,), minval=0.3, maxval=WORLD - 0.3),\n            "gy": jax.random.uniform(k3, (B,), minval=0.3, maxval=WORLD - 0.3),\n            "cur": jnp.zeros(B, jnp.int32), "phase": jnp.zeros(B, jnp.int32), "ph": jnp.zeros(B, jnp.int32),\n            "mot": 2 * jax.random.randint(k4, (B,), 0, max(1, nm)),\n            "prd": jnp.array(PERIODS, jnp.int32)[jax.random.randint(k5, (B,), 0, len(PERIODS))],\n            "tha": jnp.array(thr, jnp.int32)[jnp.zeros(B, jnp.int32)], "pmode": jnp.zeros(B, jnp.int32),\n            "at_end": jnp.ones(B, bool), "fresh": jnp.ones(B, bool)}\n\n\ndef restore(mem, feats, arch_feats, arch_valid, arch_visits, rng):\n    B = feats.shape[0]; K = arch_valid.shape[0]; N = mem["tcnt"].shape[0]\n    k1, k2, k3, k4, k5, k6, k7, k8, k9 = jax.random.split(rng, 9)\n    plan = mem["at_end"] | (jax.random.uniform(k1, (B,)) < P_BASE)\n    # ---- sample a goal: least-visited non-wall shape, or a random arena point ----\n    act = (feats[:, mem["ai"]] > 0.5).any(0)\n    okt = act & (mem["wall"] < 0.5)\n    tsc = jnp.where(okt, -jnp.log1p(mem["tcnt"]), -1e9)\n    pt = jnp.argmax(tsc[None, :] + jax.random.gumbel(k2, (B, N), jnp.float32), axis=1)\n    use_shape = (jax.random.uniform(k3, (B,)) < GOAL_BIAS) & okt.any()\n    gsel = jnp.where(plan, jnp.where(use_shape, pt, N), mem["gsel"])\n    gx = jnp.where(plan, jax.random.uniform(k4, (B,), minval=0.3, maxval=WORLD - 0.3), mem["gx"])\n    gy = jnp.where(plan, jax.random.uniform(k5, (B,), minval=0.3, maxval=WORLD - 0.3), mem["gy"])\n    chan = jnp.where(plan, jax.random.randint(k6, (B,), 0, 2), mem["chan"])\n    tcnt = mem["tcnt"].at[jnp.where(plan & use_shape, pt, 0)].add(jnp.where(plan & use_shape, 1.0, 0.0))\n    # ---- extend from the archived node whose driven body is nearest that goal ----\n    apos = jnp.stack([arch_feats[:, 0:2], arch_feats[:, 5:7]], axis=1)            # (K,2,2)\n    ap = jnp.transpose(apos, (1, 0, 2))[chan]                                     # (B,K,2)\n    ci = jnp.minimum(gsel, N - 1)\n    agx = jnp.transpose(arch_feats[:, mem["px"]])[ci]; agy = jnp.transpose(arch_feats[:, mem["py"]])[ci]\n    tx = jnp.where((gsel < N)[:, None], agx, gx[:, None]); ty = jnp.where((gsel < N)[:, None], agy, gy[:, None])\n    dd = jnp.sqrt((ap[:, :, 0] - tx) ** 2 + (ap[:, :, 1] - ty) ** 2 + 1e-9)\n    key = dd + VIS_W * jnp.log1p(arch_visits.astype(jnp.float32))[None, :] + NOISE * jax.random.exponential(k7, (B, K))\n    slot = jnp.argmin(jnp.where(arch_valid[None, :], key, 1e9), axis=1)\n    do = plan & arch_valid.any()\n    pl = jax.random.randint(k8, (B,), PUMP_MIN, PUMP_MAX + 1)\n    k10, k11, k12 = jax.random.split(k9, 3)\n    return do, slot, {**mem, "gsel": gsel, "gx": gx, "gy": gy, "chan": chan, "tcnt": tcnt,\n                      "phase": jnp.where(plan, (pl <= 0).astype(jnp.int32), mem["phase"]),\n                      "ph": jnp.where(plan, jnp.where(pl > 0, pl, AIM_L), mem["ph"]),\n                      "mot": jnp.where(plan, 2 * jax.random.randint(k10, (B,), 0, jnp.maximum(mem["nm"], 1)), mem["mot"]),\n                      "prd": jnp.where(plan, mem["per"][jax.random.randint(k11, (B,), 0, mem["per"].shape[0])], mem["prd"]),\n                      "tha": jnp.where(plan, mem["thr"][jax.random.randint(k12, (B,), 0, mem["thr"].shape[0])], mem["tha"]),\n                      "pmode": jnp.where(plan, jax.random.randint(k8, (B,), 0, 2), mem["pmode"]),\n                      "M": jnp.where(do[:, None, None, None], MDECAY * mem["M"], mem["M"]),\n                      "at_end": jnp.zeros(B, bool), "fresh": mem["fresh"] | do}\n\n\ndef act(mem, feats, obs, rng):\n    B = feats.shape[0]; N = mem["tcnt"].shape[0]; ar = jnp.arange(B)\n    k1, k2, k3 = jax.random.split(rng, 3)\n    pos, vel = _bodies(mem, feats)\n    # ---- online per-action acceleration model of each driven body ----\n    dv = vel - mem["pv"]\n    oh = (jnp.arange(mem["M"].shape[2]) == mem["cur"][:, None]).astype(jnp.float32)      # (B,n_act)\n    tgtM = dv[:, :, None, :]                                                             # (B,2,1,2)\n    upd = (~mem["fresh"])[:, None, None, None] * oh[:, None, :, None]\n    M = mem["M"] + LR * upd * (tgtM - mem["M"])\n    # ---- aim: the action whose learnt acceleration best aligns with the goal direction ----\n    p = pos[ar, mem["chan"]]\n    sx = feats[:, mem["px"]][ar, jnp.minimum(mem["gsel"], N - 1)]\n    sy = feats[:, mem["py"]][ar, jnp.minimum(mem["gsel"], N - 1)]\n    gx = jnp.where(mem["gsel"] < N, sx, mem["gx"]); gy = jnp.where(mem["gsel"] < N, sy, mem["gy"])\n    ux = gx - p[:, 0]; uy = gy - p[:, 1]; nn = jnp.sqrt(ux * ux + uy * uy) + 1e-6\n    Mc = M[ar, mem["chan"]]                                                              # (B,n_act,2)\n    score = (Mc[:, :, 0] * (ux / nn)[:, None] + Mc[:, :, 1] * (uy / nn)[:, None])\n    a_aim = jnp.argmax(score / TAU + jax.random.gumbel(k1, score.shape, jnp.float32), axis=1)\n    a_aim = jnp.where(jax.random.uniform(k2, (B,)) < EPS_RAND, jax.random.randint(k3, (B,), 0, mem["n_act"]), a_aim)\n    # ---- pump: resonant motor square wave or thruster hold ----\n    a_pump = jnp.where(mem["pmode"] == 0, mem["mot"] + (mem["ph"] // jnp.maximum(mem["prd"], 1)) % 2, mem["tha"])\n    a = jnp.where(mem["phase"] == 0, a_pump, a_aim).astype(jnp.int32)\n    nph = mem["ph"] - 1\n    to_aim = (nph <= 0) & (mem["phase"] == 0)\n    done_ext = (nph <= 0) & (mem["phase"] == 1)\n    return a, {**mem, "M": M, "pv": vel, "cur": a, "fresh": jnp.zeros(B, bool),\n               "phase": jnp.where(to_aim, 1, mem["phase"]),\n               "ph": jnp.where(to_aim, AIM_L, nph), "at_end": done_ext}\n\n\ndef archive(mem, feats, done, arch_feats, arch_valid, rng):\n    B = feats.shape[0]; K = arch_valid.shape[0]\n    k1, k2, k3 = jax.random.split(rng, 3)\n    pos, vel = _bodies(mem, feats)\n    p = pos[jnp.arange(B), mem["chan"]]\n    cw = WORLD / mem["R"].astype(jnp.float32)\n    cx = jnp.clip((p[:, 0] / cw).astype(jnp.int32), 0, mem["R"] - 1)\n    cy = jnp.clip((p[:, 1] / cw).astype(jnp.int32), 0, mem["R"] - 1)\n    g_slot = jnp.clip(mem["chan"] * mem["R"] * mem["R"] + cy * mem["R"] + cx, 0, K - 1)\n    q = feats[:, 4]\n    fresh_cell = ~mem["occ"][g_slot]\n    beats = q > mem["qbest"][g_slot] - Q_EPS\n    grid = fresh_cell | beats | (jax.random.uniform(k1, (B,)) < P_REF)\n    ntail = jnp.maximum(K - mem["G"], 1)\n    r_slot = mem["G"] + (mem["res"] + jnp.arange(B)) % ntail\n    use_res = (jax.random.uniform(k2, (B,)) < P_RES) & (K > mem["G"])\n    slot = jnp.where(use_res, jnp.clip(r_slot, 0, K - 1), g_slot)\n    store = (~done) & (grid | use_res)\n    upd = store & ~use_res\n    qbest = mem["qbest"].at[jnp.where(upd, g_slot, 0)].max(jnp.where(upd, q, -1e6))\n    occ = mem["occ"].at[jnp.where(store, slot, 0)].max(store)\n    return store, slot, {**mem, "qbest": qbest, "occ": occ, "res": (mem["res"] + use_res.sum()) % ntail}\n# EVOLVE-BLOCK-END\n\n\n']
_P = []
for _s in _SRC:
    _ns = {"jax": jax, "jnp": jnp}
    exec(_s, _ns)
    _P.append(_ns)
N_SUB = len(_P)


def _sel(outs_b, group):
    """outs_b: list of (B,) arrays, one per sub-program -> per-worker selection by group."""
    st = jnp.stack(outs_b)
    return st[group, jnp.arange(group.shape[0])]


def init(rng, F, n_act, K, B):
    keys = jax.random.split(rng, N_SUB)
    Ki = K // N_SUB
    return {"sub": [_P[i]["init"](keys[i], F, n_act, Ki, B) for i in range(N_SUB)], "group": jnp.arange(B) % N_SUB, "Ki": jnp.int32(Ki)}


def restore(mem, feats, arch_feats, arch_valid, arch_visits, rng):
    keys = jax.random.split(rng, N_SUB); Ki = arch_valid.shape[0] // N_SUB
    dos, slots, subs = [], [], []
    for i in range(N_SUB):
        sl = slice(i * Ki, (i + 1) * Ki)
        d, s, m = _P[i]["restore"](mem["sub"][i], feats, arch_feats[sl], arch_valid[sl], arch_visits[sl], keys[i])
        dos.append(d); slots.append(jnp.clip(s, 0, Ki - 1) + i * Ki); subs.append(m)
    g = mem["group"]
    return _sel(dos, g), _sel(slots, g), {**mem, "sub": subs}


def act(mem, feats, obs, rng):
    keys = jax.random.split(rng, N_SUB); acts, subs = [], []
    for i in range(N_SUB):
        a, m = _P[i]["act"](mem["sub"][i], feats, obs, keys[i]); acts.append(a); subs.append(m)
    return _sel(acts, mem["group"]), {**mem, "sub": subs}


def archive(mem, feats, done, arch_feats, arch_valid, rng):
    keys = jax.random.split(rng, N_SUB); Ki = arch_valid.shape[0] // N_SUB
    dos, slots, subs = [], [], []
    for i in range(N_SUB):
        sl = slice(i * Ki, (i + 1) * Ki)
        d, s, m = _P[i]["archive"](mem["sub"][i], feats, done, arch_feats[sl], arch_valid[sl], keys[i])
        # only this sub-program's own workers may store into its partition
        d = d & (mem["group"] == i)
        dos.append(d); slots.append(jnp.clip(s, 0, Ki - 1) + i * Ki); subs.append(m)
    g = mem["group"]
    return _sel(dos, g), _sel(slots, g), {**mem, "sub": subs}
# EVOLVE-BLOCK-END


def run_experiment(**kwargs):
    """Called by the evaluation harness; returns the search-split fitness. Do not edit."""
    import sys, os
    sys.path.insert(0, os.environ.get("AUTODEV_ROOT", os.path.dirname(os.path.dirname(os.path.abspath(__file__)))))
    from autodev.search_eval import evaluate_hooks
    return evaluate_hooks(init, restore, act, archive, **kwargs)
